-- Greenfield STAGING hweoqkbgmzycyznrbvng ONLY. ROLLBACK REHEARSAL; never commits.
-- No passwords/Auth changes, report/source writes or existing report-role grants.
BEGIN;
SET LOCAL search_path=pg_catalog;
SET LOCAL TIME ZONE 'UTC';
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='120s';

-- Phase: preflight-and-baseline
DO $preflight$ BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=current_user AND NOT rolsuper AND rolcreaterole AND rolbypassrls) THEN RAISE EXCEPTION 'Reviewed managed postgres operator required'; END IF;
 IF current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999 THEN RAISE EXCEPTION 'Reviewed PostgreSQL 17 target required'; END IF;
 IF NOT has_schema_privilege(current_user,'public','CREATE') OR NOT has_database_privilege(current_user,current_database(),'TEMP') THEN RAISE EXCEPTION 'Managed schema/TEMP privileges required'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_attendance_owner','greenfield_attendance_runtime','greenfield_attendance_app')) THEN RAISE EXCEPTION 'Attendance roles must be absent; no adoption'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('save_attendance','read_attendance','deny_attendance_history_change')) THEN RAISE EXCEPTION 'Attendance function name already exists'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_policies WHERE schemaname='public' AND policyname IN ('attendance_private_authority_read','attendance_private_gate','attendance_private_storage')) THEN RAISE EXCEPTION 'Attendance policy name already exists'; END IF;
 IF to_regclass('pg_temp.greenfield_attendance_install_baseline') IS NOT NULL THEN RAISE EXCEPTION 'Unexpected previous temporary installation snapshot'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.schools WHERE id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid AND slug='greenfield-staging' AND final_primary_year=5) THEN RAISE EXCEPTION 'Exact fictional staging school required'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner') AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication AND NOT rolinherit AND rolcanlogin=(rolname='greenfield_app'))<>3 THEN RAISE EXCEPTION 'Existing report roles differ'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member WHERE u.rolname='greenfield_app')<>1 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE u.rolname='greenfield_app' AND r.rolname='greenfield_report_card_runtime' AND m.set_option AND NOT m.inherit_option AND NOT m.admin_option) THEN RAISE EXCEPTION 'Report LOGIN membership changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('public.lock_report_card_actor(uuid)') AND md5(pg_get_functiondef(oid))='8352578ccca06a7d0a39f448d5489d1c') THEN RAISE EXCEPTION 'Inspected helper changed: public.lock_report_card_actor(uuid)'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('public.report_card_request_auth_uid()') AND md5(pg_get_functiondef(oid))='46d583b7ea30b81fa33b33b8c2833eb7') THEN RAISE EXCEPTION 'Inspected helper changed: public.report_card_request_auth_uid()'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('public.resolve_report_card_actor()') AND md5(pg_get_functiondef(oid))='9ec1ada02e0087dea08257d738ca986c') THEN RAISE EXCEPTION 'Inspected helper changed: public.resolve_report_card_actor()'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('public.resolve_staging_staff_account()') AND md5(pg_get_functiondef(oid))='c2976268d2a3ae29413e0702eedcfed2') THEN RAISE EXCEPTION 'Inspected helper changed: public.resolve_staging_staff_account()'; END IF;
 -- Same discovery order as installed parent writers: source row, then authority barrier.
 PERFORM id FROM public.assessment_source_write_gate WHERE id=1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Coordinated source gate missing'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('greenfield.report-card.authority-gate.v1',0));
END $preflight$;
CREATE TEMP TABLE greenfield_attendance_install_baseline ON COMMIT DROP AS SELECT (SELECT jsonb_object_agg(relation,jsonb_build_object('rows',n,'marker',marker)) FROM (SELECT 'report_cards'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_cards x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'report_card_snapshots'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_card_snapshots x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'report_card_audit'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_card_audit x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'report_card_operation_receipts'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_card_operation_receipts x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'report_card_releases'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_card_releases x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_scopes'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_scopes x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_scores'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_scores x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_source_versions'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_source_versions x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_teacher_reviews'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_teacher_reviews x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_finalizations'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_finalizations x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_audit'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_audit x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_operation_receipts'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_operation_receipts x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_config_versions'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_config_versions x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'enrollments'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.enrollments x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid) preserved) AS data_state,(SELECT jsonb_build_object('roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname) FROM (SELECT rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner')) r),'edges',(SELECT jsonb_agg(to_jsonb(e) ORDER BY e.member,e.role,e.grantor) FROM (SELECT u.rolname AS member,r.rolname AS role,g.rolname AS grantor,m.admin_option,m.inherit_option,m.set_option FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles r ON r.oid=m.roleid JOIN pg_catalog.pg_roles g ON g.oid=m.grantor WHERE u.rolname IN ('greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner') OR r.rolname IN ('greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner')) e))) AS role_state,(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'acl',p.proacl,'owner',p.proowner) ORDER BY p.oid::regprocedure::text) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND p.proname IN ('lock_report_card_actor','resolve_report_card_actor','report_card_request_auth_uid','resolve_staging_staff_account','lock_report_card_authority_write_gate','lock_report_card_membership_actor_anchor','assessment_lock_source_write','assessment_mark_source_scope','assessment_invalidate_source_rows','assessment_reject_source_truncate','assessment_invalidate_parent_rows','report_card_reject_history','report_card_guard_release_history','report_card_restrict_runtime_writes')) AS helper_state,(SELECT jsonb_agg(jsonb_build_object('relation',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND c.relname NOT IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts')) AS trigger_state,(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_catalog.pg_policies p WHERE schemaname='public' AND policyname NOT IN ('attendance_private_authority_read','attendance_private_gate','attendance_private_storage')) AS policy_state;

-- Phase: managed-role-bootstrap
CREATE ROLE greenfield_attendance_owner NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB NOREPLICATION;
CREATE ROLE greenfield_attendance_runtime NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB NOREPLICATION;
CREATE ROLE greenfield_attendance_app LOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB NOREPLICATION PASSWORD NULL;
GRANT greenfield_attendance_owner TO postgres WITH ADMIN FALSE GRANTED BY postgres;
GRANT greenfield_attendance_owner TO postgres WITH INHERIT FALSE GRANTED BY postgres;
GRANT greenfield_attendance_owner TO postgres WITH SET TRUE GRANTED BY postgres;
GRANT CREATE ON SCHEMA public TO greenfield_attendance_owner;
GRANT CONNECT ON DATABASE postgres TO greenfield_attendance_app;
GRANT greenfield_attendance_runtime TO greenfield_attendance_app WITH ADMIN FALSE GRANTED BY postgres;
GRANT greenfield_attendance_runtime TO greenfield_attendance_app WITH INHERIT FALSE GRANTED BY postgres;
GRANT greenfield_attendance_runtime TO greenfield_attendance_app WITH SET TRUE GRANTED BY postgres;

-- Phase: additive-storage-functions-policy
DO $p$ BEGIN
 IF (SELECT count(*) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('schools','school_users','memberships','classes','academic_levels','academic_sections','academic_sessions','students','enrollments','teacher_class_assignments','assessment_source_write_gate') AND c.relrowsecurity AND c.relforcerowsecurity)<>11 THEN RAISE EXCEPTION 'Forced foundation RLS required'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_policy p JOIN pg_catalog.pg_class c ON c.oid=p.polrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('schools','school_users','memberships','classes','academic_levels','academic_sections','academic_sessions','students','enrollments','teacher_class_assignments','assessment_source_write_gate') AND NOT p.polpermissive AND 0::oid=ANY(p.polroles)) THEN RAISE EXCEPTION 'PUBLIC restrictive policy requires separate complete-authority review'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts')) THEN RAISE EXCEPTION 'Attendance extension must be absent'; END IF;
 IF NOT EXISTS(SELECT 1 FROM "public"."schools" WHERE id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid AND final_primary_year=5) THEN RAISE EXCEPTION 'Reviewed Primary 5 school required'; END IF;
 IF (SELECT count(*) FROM "public"."classes" c JOIN "public"."academic_levels" l ON l.school_id=c.school_id AND l.id=c.level_id JOIN "public"."academic_sections" s ON s.school_id=c.school_id AND s.id=c.section_id AND s.level_id=l.id WHERE c.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid AND l.is_active AND s.is_active AND ((c.id='1dbfa5e7-99b8-5094-b1f9-c872477d4bf6'::uuid AND l.stage='primary' AND l.primary_year=5) OR (c.id='fe6e5a74-b93a-5d00-8115-53b6952153be'::uuid AND l.stage='creche')))<>2 THEN RAISE EXCEPTION 'Class mapping differs from reviewed structure'; END IF;
 IF NOT EXISTS(SELECT 1 FROM "public"."assessment_source_write_gate" WHERE id=1) THEN RAISE EXCEPTION 'Coordinated source gate required'; END IF;
 END $p$;
CREATE TABLE "public"."attendance_registers" (id uuid PRIMARY KEY, school_id uuid NOT NULL, class_id uuid NOT NULL, session_id uuid NOT NULL, register_date date NOT NULL, version integer NOT NULL CHECK(version>0), FOREIGN KEY(school_id,class_id) REFERENCES "public"."classes"(school_id,id), FOREIGN KEY(school_id,session_id) REFERENCES "public"."academic_sessions"(school_id,id), UNIQUE(school_id,class_id,session_id,register_date), UNIQUE(school_id,id,class_id,session_id,register_date));
CREATE TABLE "public"."attendance_marks" (school_id uuid NOT NULL, register_id uuid NOT NULL, student_id uuid NOT NULL, enrollment_id uuid NOT NULL, class_id uuid NOT NULL, session_id uuid NOT NULL, register_date date NOT NULL, status text NOT NULL CHECK(status IN ('present','absent','late','excused')), PRIMARY KEY(school_id,register_id,student_id), UNIQUE(school_id,student_id,register_date), FOREIGN KEY(school_id,register_id,class_id,session_id,register_date) REFERENCES "public"."attendance_registers"(school_id,id,class_id,session_id,register_date), FOREIGN KEY(school_id,enrollment_id,student_id,class_id,session_id) REFERENCES "public"."enrollments"(school_id,id,student_id,class_id,session_id));
CREATE TABLE "public"."attendance_audit" (id uuid PRIMARY KEY, school_id uuid NOT NULL, register_id uuid NOT NULL, class_id uuid NOT NULL, session_id uuid NOT NULL, register_date date NOT NULL, actor_id uuid NOT NULL, version integer NOT NULL CHECK(version>0), reason text, marks jsonb NOT NULL CHECK(jsonb_typeof(marks)='object'), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), CHECK((version=1 AND reason IS NULL) OR (version>1 AND reason IS NOT NULL AND length(btrim(reason)) BETWEEN 1 AND 2000)), FOREIGN KEY(school_id,actor_id) REFERENCES "public"."memberships"(school_id,id), FOREIGN KEY(school_id,register_id,class_id,session_id,register_date) REFERENCES "public"."attendance_registers"(school_id,id,class_id,session_id,register_date), UNIQUE(school_id,register_id,version), UNIQUE(school_id,id,actor_id,version));
CREATE TABLE "public"."attendance_receipts" (school_id uuid NOT NULL, actor_id uuid NOT NULL, operation_key text NOT NULL CHECK(operation_key ~ '^[A-Za-z0-9:_-]{8,120}$'), command jsonb NOT NULL CHECK(jsonb_typeof(command)='object'), audit_id uuid NOT NULL, version integer NOT NULL, PRIMARY KEY(school_id,actor_id,operation_key), FOREIGN KEY(school_id,audit_id,actor_id,version) REFERENCES "public"."attendance_audit"(school_id,id,actor_id,version));
GRANT USAGE ON SCHEMA "public" TO "greenfield_attendance_owner","greenfield_attendance_runtime";
GRANT SELECT ON "public"."schools" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."school_users" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."memberships" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."classes" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."academic_levels" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."academic_sections" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."academic_sessions" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."students" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."enrollments" TO "greenfield_attendance_owner";
GRANT SELECT ON "public"."teacher_class_assignments" TO "greenfield_attendance_owner";
CREATE POLICY attendance_private_authority_read ON "public"."schools" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."school_users" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."memberships" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."classes" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."academic_levels" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."academic_sections" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."academic_sessions" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."students" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."enrollments" FOR SELECT TO "greenfield_attendance_owner" USING(true);
CREATE POLICY attendance_private_authority_read ON "public"."teacher_class_assignments" FOR SELECT TO "greenfield_attendance_owner" USING(true);
GRANT SELECT,UPDATE(id) ON "public"."assessment_source_write_gate" TO "greenfield_attendance_owner";
CREATE POLICY attendance_private_gate ON "public"."assessment_source_write_gate" TO "greenfield_attendance_owner" USING(id=1) WITH CHECK(false);
CREATE FUNCTION "public"."deny_attendance_history_change"() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog SET row_security=on AS $f$ BEGIN RAISE EXCEPTION 'Attendance history is immutable' USING ERRCODE='42501'; END $f$;
CREATE FUNCTION "public"."save_attendance"(verified_auth uuid, cmd jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $f$
DECLARE actor record; klass record; sess record; reg record; prior record; day date; expected integer; n integer; audit_uuid uuid; register_uuid uuid; marks jsonb; canonical jsonb;
BEGIN
 -- Trusted fixture server passes verified_auth; never expose this UUID-taking API through PostgREST.
 -- A single exclusive fixture gate serializes register and authority discovery, including empty writes.
 PERFORM id FROM "public"."assessment_source_write_gate" WHERE id=1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing attendance gate'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('greenfield.report-card.authority-gate.v1',0));
 IF cmd IS NULL OR jsonb_typeof(cmd)<>'object' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(cmd))<>7 OR NOT (cmd ?& ARRAY['action','classKey','date','expectedVersion','operationKey','reason','marks'])
 OR cmd->>'action'<>'save_register' OR cmd->>'classKey' NOT IN ('primary5','creche')
 OR jsonb_typeof(cmd->'action')<>'string' OR jsonb_typeof(cmd->'classKey')<>'string'
 OR jsonb_typeof(cmd->'date')<>'string' OR cmd->>'date' !~ '^\d{4}-\d{2}-\d{2}$'
 OR jsonb_typeof(cmd->'expectedVersion')<>'number' OR cmd->>'expectedVersion' !~ '^(0|[1-9][0-9]{0,9})$'
 OR (cmd->>'expectedVersion')::numeric>=2147483647
 OR jsonb_typeof(cmd->'operationKey')<>'string' OR cmd->>'operationKey' !~ '^[A-Za-z0-9:_-]{8,120}$'
 OR jsonb_typeof(cmd->'marks')<>'object' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 expected:=(cmd->>'expectedVersion')::integer; marks:=cmd->'marks';
 IF (expected=0 AND cmd->'reason'<>'null'::jsonb) OR (expected>0 AND (jsonb_typeof(cmd->'reason')<>'string' OR length(btrim(cmd->>'reason')) NOT BETWEEN 1 AND 2000)) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 BEGIN day:=(cmd->>'date')::date; EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END;
 IF to_char(day,'YYYY-MM-DD')<>cmd->>'date' OR day>(CURRENT_TIMESTAMP AT TIME ZONE 'Africa/Lagos')::date THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_each(marks)) OR EXISTS(SELECT 1 FROM jsonb_each(marks) e WHERE e.key !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(e.value)<>'string' OR e.value#>>'{}' NOT IN ('present','absent','late','excused')) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 -- Complete membership set is visible to the private fixture owner, without client school scope.
 IF (SELECT count(*) FROM "public"."school_users" WHERE auth_user_id=verified_auth)<>1 OR (SELECT count(*) FROM "public"."memberships" m JOIN "public"."school_users" u ON u.id=m.user_id WHERE u.auth_user_id=verified_auth AND m.status='active')<>1 THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 SELECT m.* INTO actor FROM "public"."memberships" m JOIN "public"."school_users" u ON u.id=m.user_id WHERE u.auth_user_id=verified_auth AND m.status='active';
 IF actor.school_id<>'0c594571-74c5-46fe-a835-a9b217a3a199'::uuid OR actor.role NOT IN ('admin','teacher') THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 SELECT c.* INTO klass FROM "public"."classes" c JOIN "public"."academic_levels" l ON l.school_id=c.school_id AND l.id=c.level_id JOIN "public"."academic_sections" s ON s.school_id=c.school_id AND s.id=c.section_id AND s.level_id=l.id WHERE c.school_id=actor.school_id AND l.is_active AND s.is_active AND ((c.id='1dbfa5e7-99b8-5094-b1f9-c872477d4bf6'::uuid AND l.stage='primary' AND l.primary_year=5) OR (c.id='fe6e5a74-b93a-5d00-8115-53b6952153be'::uuid AND l.stage='creche')) AND c.id=CASE cmd->>'classKey' WHEN 'primary5' THEN '1dbfa5e7-99b8-5094-b1f9-c872477d4bf6'::uuid WHEN 'creche' THEN 'fe6e5a74-b93a-5d00-8115-53b6952153be'::uuid END;
 IF NOT FOUND THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 IF (SELECT count(*) FROM "public"."academic_sessions" WHERE school_id=actor.school_id AND is_current)<>1 THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 SELECT * INTO sess FROM "public"."academic_sessions" WHERE school_id=actor.school_id AND is_current;
 IF day NOT BETWEEN sess.starts_on AND sess.ends_on THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF actor.role='teacher' AND (SELECT count(*) FROM "public"."teacher_class_assignments" WHERE school_id=actor.school_id AND teacher_membership_id=actor.id AND class_id=klass.id AND session_id=sess.id AND ended_at IS NULL)<>1 THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 canonical:=cmd || jsonb_build_object('reason',CASE WHEN expected=0 THEN NULL ELSE btrim(cmd->>'reason') END);
 SELECT * INTO prior FROM "public"."attendance_receipts" WHERE school_id=actor.school_id AND actor_id=actor.id AND operation_key=cmd->>'operationKey';
 IF FOUND THEN IF prior.command=canonical THEN RETURN jsonb_build_object('ok',true,'kind','replay','version',prior.version); ELSE RETURN '{"ok":false,"code":"conflict"}'::jsonb; END IF; END IF;
 -- Historical replay above needs current authority, but does not rewrite the old roster.
 SELECT count(*) INTO n FROM "public"."enrollments" e JOIN "public"."students" s ON s.school_id=e.school_id AND s.id=e.student_id AND s.status='active' WHERE e.school_id=actor.school_id AND e.class_id=klass.id AND e.session_id=sess.id AND e.status='active';
 IF n=0 OR n<>(SELECT count(*) FROM jsonb_object_keys(marks)) OR n<>(SELECT count(DISTINCT e.student_id) FROM "public"."enrollments" e JOIN "public"."students" s ON s.school_id=e.school_id AND s.id=e.student_id AND s.status='active' WHERE e.school_id=actor.school_id AND e.class_id=klass.id AND e.session_id=sess.id AND e.status='active')
 OR EXISTS(SELECT 1 FROM "public"."enrollments" e JOIN "public"."students" s ON s.school_id=e.school_id AND s.id=e.student_id AND s.status='active' WHERE e.school_id=actor.school_id AND e.class_id=klass.id AND e.session_id=sess.id AND e.status='active' AND (NOT marks ? e.student_id::text OR (SELECT count(*) FROM "public"."enrollments" x WHERE x.school_id=e.school_id AND x.student_id=e.student_id AND x.session_id=e.session_id AND x.status='active')<>1)) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 SELECT * INTO reg FROM "public"."attendance_registers" WHERE school_id=actor.school_id AND class_id=klass.id AND session_id=sess.id AND register_date=day FOR UPDATE;
 IF (FOUND AND reg.version<>expected) OR (NOT FOUND AND expected<>0) THEN RETURN '{"ok":false,"code":"conflict"}'::jsonb; END IF;
 IF expected>0 AND (EXISTS(SELECT 1 FROM "public"."attendance_marks" m WHERE m.school_id=actor.school_id AND m.register_id=reg.id AND NOT EXISTS(SELECT 1 FROM "public"."enrollments" e WHERE e.school_id=m.school_id AND e.id=m.enrollment_id AND e.class_id=klass.id AND e.session_id=sess.id AND e.status='active' AND marks ? e.student_id::text)) OR (SELECT count(*) FROM "public"."attendance_marks" WHERE school_id=actor.school_id AND register_id=reg.id)<>n) THEN RETURN '{"ok":false,"code":"conflict"}'::jsonb; END IF;
 register_uuid:=CASE WHEN expected=0 THEN gen_random_uuid() ELSE reg.id END;
 IF expected=0 THEN INSERT INTO "public"."attendance_registers" VALUES(register_uuid,actor.school_id,klass.id,sess.id,day,1); ELSE UPDATE "public"."attendance_registers" SET version=expected+1 WHERE id=register_uuid; END IF;
 INSERT INTO "public"."attendance_marks"(school_id,register_id,student_id,enrollment_id,class_id,session_id,register_date,status)
 SELECT e.school_id,register_uuid,e.student_id,e.id,e.class_id,e.session_id,day,marks->>e.student_id::text FROM "public"."enrollments" e JOIN "public"."students" s ON s.school_id=e.school_id AND s.id=e.student_id AND s.status='active' WHERE e.school_id=actor.school_id AND e.class_id=klass.id AND e.session_id=sess.id AND e.status='active'
 ON CONFLICT(school_id,register_id,student_id) DO UPDATE SET status=EXCLUDED.status;
 audit_uuid:=gen_random_uuid();
 INSERT INTO "public"."attendance_audit"(id,school_id,register_id,class_id,session_id,register_date,actor_id,version,reason,marks) VALUES(audit_uuid,actor.school_id,register_uuid,klass.id,sess.id,day,actor.id,expected+1,canonical->>'reason',marks);
 INSERT INTO "public"."attendance_receipts" VALUES(actor.school_id,actor.id,cmd->>'operationKey',canonical,audit_uuid,expected+1);
 RETURN jsonb_build_object('ok',true,'kind','applied','version',expected+1);
END $f$;
CREATE FUNCTION "public"."read_attendance"(verified_auth uuid, class_key text, selected_date date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $f$
DECLARE actor record; klass record; sess record; reg record; marks jsonb; history jsonb;
BEGIN
 PERFORM id FROM "public"."assessment_source_write_gate" WHERE id=1 FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing coordinated source gate'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('greenfield.report-card.authority-gate.v1',0));
 IF class_key IS NULL OR class_key NOT IN ('primary5','creche') OR selected_date IS NULL THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF (SELECT count(*) FROM "public"."school_users" WHERE auth_user_id=verified_auth)<>1 OR (SELECT count(*) FROM "public"."memberships" m JOIN "public"."school_users" u ON u.id=m.user_id WHERE u.auth_user_id=verified_auth AND m.status='active')<>1 THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 SELECT m.* INTO actor FROM "public"."memberships" m JOIN "public"."school_users" u ON u.id=m.user_id WHERE u.auth_user_id=verified_auth AND m.status='active';
 IF actor.school_id<>'0c594571-74c5-46fe-a835-a9b217a3a199'::uuid OR actor.role NOT IN ('admin','teacher') THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 SELECT c.* INTO klass FROM "public"."classes" c JOIN "public"."academic_levels" l ON l.school_id=c.school_id AND l.id=c.level_id JOIN "public"."academic_sections" s ON s.school_id=c.school_id AND s.id=c.section_id AND s.level_id=l.id WHERE c.school_id=actor.school_id AND l.is_active AND s.is_active AND ((c.id='1dbfa5e7-99b8-5094-b1f9-c872477d4bf6'::uuid AND l.stage='primary' AND l.primary_year=5) OR (c.id='fe6e5a74-b93a-5d00-8115-53b6952153be'::uuid AND l.stage='creche')) AND c.id=CASE class_key WHEN 'primary5' THEN '1dbfa5e7-99b8-5094-b1f9-c872477d4bf6'::uuid WHEN 'creche' THEN 'fe6e5a74-b93a-5d00-8115-53b6952153be'::uuid END;
 IF NOT FOUND OR (SELECT count(*) FROM "public"."academic_sessions" WHERE school_id=actor.school_id AND is_current)<>1 THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 SELECT * INTO sess FROM "public"."academic_sessions" WHERE school_id=actor.school_id AND is_current;
 IF selected_date NOT BETWEEN sess.starts_on AND sess.ends_on OR selected_date>(CURRENT_TIMESTAMP AT TIME ZONE 'Africa/Lagos')::date THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF actor.role='teacher' AND (SELECT count(*) FROM "public"."teacher_class_assignments" WHERE school_id=actor.school_id AND teacher_membership_id=actor.id AND class_id=klass.id AND session_id=sess.id AND ended_at IS NULL)<>1 THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 SELECT * INTO reg FROM "public"."attendance_registers" WHERE school_id=actor.school_id AND class_id=klass.id AND session_id=sess.id AND register_date=selected_date FOR SHARE;
 IF NOT FOUND THEN RETURN '{"ok":true,"register":null}'::jsonb; END IF;
 SELECT jsonb_object_agg(student_id::text,status) INTO marks FROM "public"."attendance_marks" WHERE school_id=actor.school_id AND register_id=reg.id;
 SELECT jsonb_agg(jsonb_build_object('version',version,'reason',reason,'marks',a.marks,'recordedAt',to_char(created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ORDER BY version) INTO history FROM "public"."attendance_audit" a WHERE school_id=actor.school_id AND register_id=reg.id;
 RETURN jsonb_build_object('ok',true,'register',jsonb_build_object('version',reg.version,'date',reg.register_date::text,'marks',marks,'history',history));
END $f$;
REVOKE ALL ON FUNCTION "public"."deny_attendance_history_change"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "public"."save_attendance"(uuid,jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION "public"."read_attendance"(uuid,text,date) FROM PUBLIC;
CREATE TRIGGER attendance_append_only BEFORE UPDATE OR DELETE OR TRUNCATE ON "public"."attendance_audit" FOR EACH STATEMENT EXECUTE FUNCTION "public"."deny_attendance_history_change"();
CREATE TRIGGER attendance_append_only BEFORE UPDATE OR DELETE OR TRUNCATE ON "public"."attendance_receipts" FOR EACH STATEMENT EXECUTE FUNCTION "public"."deny_attendance_history_change"();
CREATE TRIGGER attendance_no_delete BEFORE DELETE OR TRUNCATE ON "public"."attendance_registers" FOR EACH STATEMENT EXECUTE FUNCTION "public"."deny_attendance_history_change"();
CREATE TRIGGER attendance_no_delete BEFORE DELETE OR TRUNCATE ON "public"."attendance_marks" FOR EACH STATEMENT EXECUTE FUNCTION "public"."deny_attendance_history_change"();
REVOKE ALL ON "public"."attendance_registers" FROM PUBLIC;
ALTER TABLE "public"."attendance_registers" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."attendance_registers" FORCE ROW LEVEL SECURITY;
CREATE POLICY attendance_private_storage ON "public"."attendance_registers" TO "greenfield_attendance_owner" USING(true) WITH CHECK(true);
REVOKE ALL ON "public"."attendance_marks" FROM PUBLIC;
ALTER TABLE "public"."attendance_marks" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."attendance_marks" FORCE ROW LEVEL SECURITY;
CREATE POLICY attendance_private_storage ON "public"."attendance_marks" TO "greenfield_attendance_owner" USING(true) WITH CHECK(true);
REVOKE ALL ON "public"."attendance_audit" FROM PUBLIC;
ALTER TABLE "public"."attendance_audit" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."attendance_audit" FORCE ROW LEVEL SECURITY;
CREATE POLICY attendance_private_storage ON "public"."attendance_audit" TO "greenfield_attendance_owner" USING(true) WITH CHECK(true);
REVOKE ALL ON "public"."attendance_receipts" FROM PUBLIC;
ALTER TABLE "public"."attendance_receipts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."attendance_receipts" FORCE ROW LEVEL SECURITY;
CREATE POLICY attendance_private_storage ON "public"."attendance_receipts" TO "greenfield_attendance_owner" USING(true) WITH CHECK(true);

-- Phase: new-object-access-reset
DO $new_object_acl_reset$ DECLARE item record; principal text; BEGIN
 FOR item IN SELECT c.relname,a.grantee FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) a WHERE n.nspname='public' AND c.relname IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts') AND a.grantee<>(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) LOOP
 principal:=CASE WHEN item.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(item.grantee)) END;
 EXECUTE format('REVOKE ALL ON TABLE public.%I FROM %s',item.relname,principal); END LOOP;
 FOR item IN SELECT c.relname,col.attname,a.grantee FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_attribute col ON col.attrelid=c.oid CROSS JOIN LATERAL pg_catalog.aclexplode(col.attacl) a WHERE n.nspname='public' AND c.relname IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts') AND a.grantee<>(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) LOOP
 principal:=CASE WHEN item.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(item.grantee)) END;
 EXECUTE format('REVOKE ALL (%I) ON TABLE public.%I FROM %s',item.attname,item.relname,principal); END LOOP;
 FOR item IN SELECT p.oid::pg_catalog.regprocedure AS signature,a.grantee FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(p.proacl,pg_catalog.acldefault('f',p.proowner))) a WHERE n.nspname='public' AND p.proname IN ('save_attendance','read_attendance','deny_attendance_history_change') AND a.grantee<>(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) LOOP
 principal:=CASE WHEN item.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(item.grantee)) END;
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %s',item.signature,principal); END LOOP;
 END $new_object_acl_reset$;

-- Phase: deferred-ownership-and-cleanup
GRANT EXECUTE ON FUNCTION public.save_attendance(uuid,jsonb),public.read_attendance(uuid,text,date) TO greenfield_attendance_runtime;
ALTER TABLE public.attendance_registers OWNER TO greenfield_attendance_owner;
ALTER TABLE public.attendance_marks OWNER TO greenfield_attendance_owner;
ALTER TABLE public.attendance_audit OWNER TO greenfield_attendance_owner;
ALTER TABLE public.attendance_receipts OWNER TO greenfield_attendance_owner;
ALTER FUNCTION public.deny_attendance_history_change() OWNER TO greenfield_attendance_owner;
ALTER FUNCTION public.save_attendance(uuid,jsonb) OWNER TO greenfield_attendance_owner;
ALTER FUNCTION public.read_attendance(uuid,text,date) OWNER TO greenfield_attendance_owner;
SET LOCAL ROLE greenfield_attendance_owner;
DO $unbound_probe$ BEGIN
 IF public.save_attendance(NULL,'{}'::jsonb) IS DISTINCT FROM '{"ok":false,"code":"invalid"}'::jsonb THEN RAISE EXCEPTION 'Unbound save must reject'; END IF;
 IF public.read_attendance(NULL,'primary5',CURRENT_DATE) IS DISTINCT FROM '{"ok":false,"code":"forbidden"}'::jsonb THEN RAISE EXCEPTION 'Unbound history must reject'; END IF;
END $unbound_probe$;
RESET ROLE;
REVOKE CREATE ON SCHEMA public FROM greenfield_attendance_owner;
REVOKE greenfield_attendance_owner FROM postgres GRANTED BY postgres;

-- Phase: in-transaction-verification
DO $verify$ DECLARE name text; BEGIN
 IF (SELECT count(*) FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_attendance_owner','greenfield_attendance_runtime','greenfield_attendance_app') AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication AND NOT rolinherit AND rolcanlogin=(rolname='greenfield_attendance_app'))<>3 THEN RAISE EXCEPTION 'Attendance role flags differ'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE r.rolname IN ('greenfield_attendance_owner','greenfield_attendance_runtime','greenfield_attendance_app'))<>4 THEN RAISE EXCEPTION 'Unexpected attendance incoming membership'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid=m.roleid JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles g ON g.oid=m.grantor WHERE r.rolname IN ('greenfield_attendance_owner','greenfield_attendance_runtime','greenfield_attendance_app') AND u.rolname='postgres' AND m.admin_option AND NOT m.inherit_option AND NOT m.set_option AND g.rolsuper)<>3 THEN RAISE EXCEPTION 'Managed bootstrap ADMIN edges changed'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member WHERE u.rolname IN ('greenfield_attendance_owner','greenfield_attendance_runtime','greenfield_attendance_app'))<>1 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE u.rolname='greenfield_attendance_app' AND r.rolname='greenfield_attendance_runtime' AND m.set_option AND NOT m.inherit_option AND NOT m.admin_option) THEN RAISE EXCEPTION 'Attendance LOGIN must be SET-only'; END IF;
 IF has_schema_privilege('greenfield_attendance_owner','public','CREATE') OR has_schema_privilege('greenfield_attendance_runtime','public','CREATE') OR has_schema_privilege('greenfield_attendance_app','public','CREATE') THEN RAISE EXCEPTION 'Attendance schema CREATE leaked'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts') AND c.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='greenfield_attendance_owner') AND c.relrowsecurity AND c.relforcerowsecurity)<>4 THEN RAISE EXCEPTION 'Attendance table ownership/protection differs'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_proc p WHERE p.oid IN ('public.deny_attendance_history_change()'::regprocedure,'public.save_attendance(uuid,jsonb)'::regprocedure,'public.read_attendance(uuid,text,date)'::regprocedure) AND p.proowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='greenfield_attendance_owner') AND p.proconfig @> ARRAY['search_path=pg_catalog','row_security=on'] AND p.prosecdef=(p.proname<>'deny_attendance_history_change'))<>3 THEN RAISE EXCEPTION 'Attendance function ownership/settings differ'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(p.proacl,pg_catalog.acldefault('f',p.proowner))) a WHERE p.oid IN ('public.deny_attendance_history_change()'::regprocedure,'public.save_attendance(uuid,jsonb)'::regprocedure,'public.read_attendance(uuid,text,date)'::regprocedure) AND a.grantee<>p.proowner AND NOT (p.proname IN ('save_attendance','read_attendance') AND a.grantee=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='greenfield_attendance_runtime') AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)) THEN RAISE EXCEPTION 'Unexpected new function ACL grantee'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) a WHERE n.nspname='public' AND c.relname IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts') AND a.grantee<>c.relowner) THEN RAISE EXCEPTION 'Unexpected attendance table ACL grantee'; END IF;
 IF has_schema_privilege('greenfield_attendance_owner','auth','USAGE') THEN RAISE EXCEPTION 'Unexpected attendance Auth schema access'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_shdepend d JOIN pg_catalog.pg_roles r ON r.oid=d.refobjid WHERE d.refclassid='pg_catalog.pg_authid'::regclass AND d.deptype='o' AND r.rolname IN ('greenfield_attendance_app','greenfield_attendance_runtime')) THEN RAISE EXCEPTION 'Execution roles own objects'; END IF;
 FOREACH name IN ARRAY ARRAY['greenfield_attendance_owner','greenfield_attendance_runtime','greenfield_attendance_app','greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner','anon','authenticated','service_role'] LOOP
 IF name<>'greenfield_attendance_owner' AND EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=name) AND EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts') AND (has_table_privilege(name,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege(name,c.oid,'SELECT,INSERT,UPDATE,REFERENCES'))) THEN RAISE EXCEPTION 'Unexpected direct attendance data access: %',name; END IF;
 IF name NOT IN ('greenfield_attendance_owner','greenfield_attendance_runtime') AND EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=name) AND (has_function_privilege(name,'public.save_attendance(uuid,jsonb)','EXECUTE') OR has_function_privilege(name,'public.read_attendance(uuid,text,date)','EXECUTE')) THEN RAISE EXCEPTION 'Unexpected attendance API execution: %',name; END IF;
 END LOOP;
 IF NOT has_function_privilege('greenfield_attendance_runtime','public.save_attendance(uuid,jsonb)','EXECUTE') OR NOT has_function_privilege('greenfield_attendance_runtime','public.read_attendance(uuid,text,date)','EXECUTE') OR has_function_privilege('greenfield_attendance_runtime','public.deny_attendance_history_change()','EXECUTE') THEN RAISE EXCEPTION 'Attendance execution ACL differs'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_temp.greenfield_attendance_install_baseline b WHERE b.data_state=(SELECT jsonb_object_agg(relation,jsonb_build_object('rows',n,'marker',marker)) FROM (SELECT 'report_cards'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_cards x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'report_card_snapshots'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_card_snapshots x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'report_card_audit'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_card_audit x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'report_card_operation_receipts'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_card_operation_receipts x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'report_card_releases'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.report_card_releases x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_scopes'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_scopes x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_scores'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_scores x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_source_versions'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_source_versions x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_teacher_reviews'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_teacher_reviews x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_finalizations'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_finalizations x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_audit'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_audit x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_operation_receipts'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_operation_receipts x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_config_versions'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.assessment_config_versions x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'enrollments'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(x)::text),'' ORDER BY to_jsonb(x)::text),'')) AS marker FROM public.enrollments x WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid) preserved) AND b.role_state=(SELECT jsonb_build_object('roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname) FROM (SELECT rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner')) r),'edges',(SELECT jsonb_agg(to_jsonb(e) ORDER BY e.member,e.role,e.grantor) FROM (SELECT u.rolname AS member,r.rolname AS role,g.rolname AS grantor,m.admin_option,m.inherit_option,m.set_option FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles r ON r.oid=m.roleid JOIN pg_catalog.pg_roles g ON g.oid=m.grantor WHERE u.rolname IN ('greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner') OR r.rolname IN ('greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner')) e))) AND b.helper_state=(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'acl',p.proacl,'owner',p.proowner) ORDER BY p.oid::regprocedure::text) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND p.proname IN ('lock_report_card_actor','resolve_report_card_actor','report_card_request_auth_uid','resolve_staging_staff_account','lock_report_card_authority_write_gate','lock_report_card_membership_actor_anchor','assessment_lock_source_write','assessment_mark_source_scope','assessment_invalidate_source_rows','assessment_reject_source_truncate','assessment_invalidate_parent_rows','report_card_reject_history','report_card_guard_release_history','report_card_restrict_runtime_writes')) AND b.trigger_state=(SELECT jsonb_agg(jsonb_build_object('relation',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND c.relname NOT IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts')) AND b.policy_state=(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_catalog.pg_policies p WHERE schemaname='public' AND policyname NOT IN ('attendance_private_authority_read','attendance_private_gate','attendance_private_storage'))) THEN RAISE EXCEPTION 'Existing report/source/role/helper/guard state changed'; END IF;
 END $verify$;
ROLLBACK;
DO $rolled_back$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_attendance_owner','greenfield_attendance_runtime','greenfield_attendance_app')) OR EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('attendance_registers','attendance_marks','attendance_audit','attendance_receipts')) OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('save_attendance','read_attendance','deny_attendance_history_change')) OR EXISTS(SELECT 1 FROM pg_catalog.pg_policies WHERE schemaname='public' AND policyname IN ('attendance_private_authority_read','attendance_private_gate','attendance_private_storage')) THEN RAISE EXCEPTION 'Attendance rollback left new objects'; END IF;
 END $rolled_back$;
SELECT jsonb_build_object('attendance_managed_rollback','PASS','new_attendance_objects_absent',true,'existing_report_state_checked',true,'login_password_configured',false,'attendance_save_enabled',false) AS attendance_rollback_result;
